update application_asset_references set merge_enabled = #{row.mergeEnabled},
    description = #{row.description}, version = version + 1, updated_at = #{row.updatedAt}
where app_id = #{row.appId} and repository_id = #{row.repositoryId}
  and directory_path = #{row.directoryPath} and version = #{expectedVersion}

mapper.delete:
delete from application_asset_references
where app_id = #{appId} and repository_id = #{repositoryId}
  and directory_path = #{directoryPath} and version = #{expectedVersion}

