update application_asset_reference_import_sources
set status = 'DONE', lease_until = null, next_retry_at = null, scanned_at = #{now}, safe_error = null
where workspace_id = #{workspaceId}

update application_asset_reference_import_sources
set status = 'PENDING', lease_until = null, next_retry_at = #{retryAt}, safe_error = #{safeError}
where workspace_id = #{workspaceId}
